<?php require __DIR__.'/layouts/admin_start.php'; ?><section class="module-panel"><div class="form-actions"><a class="header-btn <?= $kind==='admin'?'primary-btn':'secondary-btn' ?>" href="?type=admin">Administrateurs</a><a class="header-btn <?= $kind==='client'?'primary-btn':'secondary-btn' ?>" href="?type=client">Clients</a></div></section><?php if($kind==='admin'): ?><section class="module-panel"><h2>Créer un administrateur</h2><form method="POST" action="/admin/utilisateurs?type=admin"><?= csrfField() ?><div class="fields"><div><label for="email">Email</label><input id="email" name="email" type="email" maxlength="190" required></div><div><label for="password">Mot de passe</label><input id="password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></div></div><div class="form-actions"><button class="header-btn primary-btn">Créer le compte</button></div></form></section><?php endif; ?><section class="module-panel"><h2><?= $kind==='admin'?'Administrateurs enregistrés':'Clients inscrits' ?></h2><table><thead><tr><th>ID</th><?php if($kind==='client'): ?><th>Nom</th><?php endif; ?><th>Email</th><?php if($kind==='client'): ?><th>Téléphone</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><?= (int)$u['id'] ?></td><?php if($kind==='client'): ?><td><?= htmlspecialchars($u['nom']) ?></td><?php endif; ?><td><?= htmlspecialchars($u['email']) ?></td><?php if($kind==='client'): ?><td><?= htmlspecialchars($u['telephone']??'') ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="<?= $kind==='client'?4:2 ?>">Aucun utilisateur.</td></tr><?php endif; ?></tbody></table><div class="module-pagination"><?php if($page>1): ?><a href="?type=<?= $kind ?>&amp;page=<?= $page-1 ?>">Précédent</a><?php endif; ?><?php if($more): ?><a href="?type=<?= $kind ?>&amp;page=<?= $page+1 ?>">Suivant</a><?php endif; ?></div></section><?php require __DIR__.'/layouts/admin_end.php'; ?>
